ALTER TABLE accounts ADD COLUMN credential_version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE products ADD COLUMN unit VARCHAR(30) NOT NULL DEFAULT 'unidad';
ALTER TABLE products ADD COLUMN ingredients VARCHAR(2000);
ALTER TABLE products ADD COLUMN allergens VARCHAR(1000);
ALTER TABLE products ADD COLUMN storage_info VARCHAR(1000);
ALTER TABLE products ADD COLUMN net_weight VARCHAR(100);
ALTER TABLE customer_orders ADD COLUMN reservation_expires_at TIMESTAMPTZ;
ALTER TABLE customer_orders ADD COLUMN payment_note VARCHAR(1000);
UPDATE customer_orders SET reservation_expires_at=now()+interval '24 hours' WHERE status='PENDIENTE_PAGO';
CREATE INDEX pending_reservation_expiry ON customer_orders(reservation_expires_at) WHERE status='PENDIENTE_PAGO';
CREATE TABLE audit_events(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),actor_id BIGINT,actor_name VARCHAR(255),action VARCHAR(30) NOT NULL,resource VARCHAR(300) NOT NULL,status INTEGER NOT NULL);
CREATE INDEX audit_events_recent ON audit_events(created_at DESC);
CREATE TABLE mail_settings(id INTEGER PRIMARY KEY CHECK(id=1),enabled BOOLEAN NOT NULL DEFAULT false,key_cipher TEXT,sender_email VARCHAR(254),sender_name VARCHAR(150),frontend_url VARCHAR(300),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO mail_settings(id,frontend_url) VALUES(1,'https://vitna-front.vercel.app');
CREATE TABLE password_reset_tokens(token_hash VARCHAR(64) PRIMARY KEY,account_id BIGINT NOT NULL REFERENCES accounts(id),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX password_reset_account ON password_reset_tokens(account_id);
CREATE TABLE mail_outbox(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,recipient VARCHAR(254) NOT NULL,subject VARCHAR(200) NOT NULL,text_cipher TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,next_attempt TIMESTAMPTZ NOT NULL DEFAULT now(),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX mail_pending ON mail_outbox(next_attempt) WHERE status='PENDING';
CREATE TABLE stock_movements(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,lot_id BIGINT NOT NULL REFERENCES lots(id),kind VARCHAR(30) NOT NULL,quantity_delta NUMERIC(38,2) NOT NULL,reserved_delta NUMERIC(38,2) NOT NULL DEFAULT 0,quantity_after NUMERIC(38,2) NOT NULL,reserved_after NUMERIC(38,2) NOT NULL,reason VARCHAR(1000) NOT NULL,actor_id BIGINT REFERENCES accounts(id),order_id BIGINT REFERENCES customer_orders(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO stock_movements(lot_id,kind,quantity_delta,quantity_after,reserved_after,reason) SELECT id,'SALDO_INICIAL',quantity,quantity,reserved,'Saldo al habilitar kardex; no reconstruye movimientos anteriores' FROM lots;
CREATE INDEX stock_movements_lot ON stock_movements(lot_id,created_at DESC);
CREATE TABLE stock_adjustments(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,lot_id BIGINT NOT NULL REFERENCES lots(id),kind VARCHAR(30) NOT NULL,delta NUMERIC(38,2) NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE',requested_by BIGINT NOT NULL REFERENCES accounts(id),reviewed_by BIGINT REFERENCES accounts(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ);
CREATE TABLE order_returns(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES customer_orders(id),product_id BIGINT NOT NULL REFERENCES products(id),lot_id BIGINT NOT NULL REFERENCES lots(id),quantity NUMERIC(38,2) NOT NULL CHECK(quantity>0),reason VARCHAR(1000) NOT NULL,actor_id BIGINT NOT NULL REFERENCES accounts(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE raw_materials(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(150) NOT NULL,unit VARCHAR(30) NOT NULL);
CREATE TABLE raw_lots(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,material_id BIGINT NOT NULL REFERENCES raw_materials(id),code VARCHAR(100) NOT NULL,warehouse VARCHAR(150) NOT NULL,quantity NUMERIC(38,2) NOT NULL CHECK(quantity>=0),expiry DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'CUARENTENA',quality_note VARCHAR(1000),UNIQUE(material_id,code));
CREATE TABLE recipes(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id),output_quantity NUMERIC(38,2) NOT NULL CHECK(output_quantity>0),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX active_recipe ON recipes(product_id) WHERE active=true;
CREATE TABLE recipe_items(recipe_id BIGINT NOT NULL REFERENCES recipes(id),material_id BIGINT NOT NULL REFERENCES raw_materials(id),quantity NUMERIC(38,2) NOT NULL CHECK(quantity>0),PRIMARY KEY(recipe_id,material_id));
CREATE TABLE production_material_plan(production_id BIGINT NOT NULL REFERENCES production_orders(id),material_id BIGINT NOT NULL REFERENCES raw_materials(id),quantity NUMERIC(38,2) NOT NULL CHECK(quantity>0),recipe_id BIGINT NOT NULL REFERENCES recipes(id),PRIMARY KEY(production_id,material_id));
CREATE TABLE raw_consumptions(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,production_id BIGINT NOT NULL REFERENCES production_orders(id),raw_lot_id BIGINT NOT NULL REFERENCES raw_lots(id),quantity NUMERIC(38,2) NOT NULL CHECK(quantity>0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(production_id,raw_lot_id));
CREATE TABLE stored_files(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,product_id BIGINT REFERENCES products(id),order_id BIGINT REFERENCES customer_orders(id),media_type VARCHAR(50) NOT NULL,content BYTEA NOT NULL,uploaded_by BIGINT NOT NULL REFERENCES accounts(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((product_id IS NULL)<>(order_id IS NULL)));
CREATE UNIQUE INDEX product_photo ON stored_files(product_id) WHERE product_id IS NOT NULL;
CREATE INDEX payment_files ON stored_files(order_id);
